import { test, expect } from '@playwright/test';

test.describe('Network Request Retry Button', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/data');
  });

  test('should display retry button when network request times out', async ({ page }) => {
    // Set up intercept to simulate network timeout
    await page.route('**/api/data', (route) => {
      route.abort('Network timeout');
    });

    // Verify initial state: no retry button visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/request failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    await expect(retryButton).toBeVisible();

    // Verify button is enabled
    await expect(retryButton).toBeEnabled();

    // Click retry button
    await retryButton.click();

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText(/request succeeded/i);
    await expect(successMessage).toBeVisible();

    // Verify data is displayed
    const dataList = page.getByRole('list');
    await expect(dataList).toBeVisible();

    // Verify data is present
    const dataItem = page.getByText('Sample Data');
    await expect(dataItem).toBeVisible();
  });

  test('should not display retry button when network request succeeds', async ({ page }) => {
    // Set up successful intercept
    await page.route('**/api/data', (route) => {
      route.continue();
    });

    // Verify initial state: no retry button visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).not.toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/request succeeded/i);
    await expect(successMessage).toBeVisible();

    // Verify data is displayed
    const dataList = page.getByRole('list');
    await expect(dataList).toBeVisible();

    // Verify data is present
    const dataItem = page.getByText('Sample Data');
    await expect(dataItem).toBeVisible();

    // Verify retry button is not visible
    await expect(retryButton).not.toBeVisible();
  });
});
